import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const read=path=>fs.readFileSync(new URL('../'+path,import.meta.url),'utf8');
const core=read('js/core.js'),discovery=read('js/discovery.js');
const premium=read('css/marketing-premium.css'),styles=read('css/discovery.css');
for(const source of [core,discovery])new vm.Script(source);
assert.match(core,/tamao-public-header/);
assert.match(core,/tamao-public-nav/);
assert.match(core,/tamao-nav-more-panel/);
assert.match(core,/tamao-nav-collapsed/);
assert.match(core,/Montar cesta/);
assert.match(core,/Moto e carro/);
assert.match(core,/onclick="go\(\\'merchants\\'\)"/);
assert.match(premium,/\.tamao-public-nav\.tamao-public-nav|\.tamao-public-header \.desktop-nav\.tamao-public-nav/);
assert.match(premium,/@media\(min-width:760px\) and \(max-width:1099px\)/);
assert.match(premium,/\.tamao-nav-more-panel \.tamao-nav-collapsed\{display:block\}/);
assert.match(premium,/@media\(max-width:759px\)/);
assert.match(discovery,/const titles=\{professionals:/);
assert.match(discovery,/Anunciar meus serviços/);
assert.match(discovery,/Oferecer uma carona/);
assert.match(discovery,/Anunciar hospedagem/);
assert.match(discovery,/eligible\.length\|\|savedIds\.length\?'<div class="discovery-tools"/);
assert.match(discovery,/Ainda não há anúncios publicados para esta busca/);
assert.match(styles,/@media\(max-width:600px\)/);
assert.match(styles,/\.discovery-hero-advertise:focus-visible/);
assert.doesNotMatch(core,/: '<button onclick="go\(\\'home\\'\)">Início<\/button><button onclick="tamaoOpenAvailability\(\)">Consultar/);
console.log('PASS: public menu, primary CTA, hero editorial, empty-state control and responsive contracts');
